 function update(state){const s={...state,calendarYear:Number.isFinite(state.calendarYear)?state.calendarYear:state.year};yearUniform.value=s.intro?1722.99:s.calendarYear;terrain.update(s);roads.update(s);city.update(s);forest.update(s);landmarks.update(s);transport.update(s);founding.update(s);targets.arrival=founding.boat.position.toArray();regional.update(s);urban.update(s);actions.update(s);exhibition.update(s);Object.assign(targets,urban.targets,actions.targets);for(const[k,v]of Object.entries(transport.targets))targets[k]=v;stats.visibleBuildings=city.visible;stats.visibleTrees=forest.visible;}
